    AFTER DBA_MAINT_DB.OVERWATCH.TASK_LOAD_HOURLY
AS
    CALL DBA_MAINT_DB.OVERWATCH.SP_INCIDENT_AUTODECLARE();

ALTER TASK IF EXISTS DBA_MAINT_DB.OVERWATCH.TASK_INCIDENT_AUTODECLARE RESUME;
