-- ===========================================================================
-- V075__security_operating_model.sql
--
-- Security operating model.
--
-- Adds:
--   * Narrow persistent login/change facts loaded after the shared QH extract.
--   * Trust Center snapshots and a latest-vs-prior delta view.
--   * A local exception-queue view that feeds Security without live history scans.
--
-- Read-only posture only. The policy-editor and access-review write surfaces that
-- earlier drafts of this migration created were removed (app v4.146.0) — Security
-- is a posture/evidence view, not an operating console.
--
-- Owner applies this migration in Snowsight after V074. The app never runs it.

EXECUTE IMMEDIATE
$$
DECLARE
    v NUMBER;
    not_ready EXCEPTION (-20075, 'V075 requires V074 first - apply migrations in order.');
BEGIN
    SELECT MAX(VERSION) INTO :v FROM DBA_MAINT_DB.OVERWATCH.SCHEMA_VERSION;
    IF (v < 74) THEN
        RAISE not_ready;
    END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS DBA_MAINT_DB.OVERWATCH.FACT_SECURITY_LOGIN_DAILY (
    DAY            DATE NOT NULL,
    USER_NAME      VARCHAR(200) NOT NULL,
    COMPANY        VARCHAR(40) NOT NULL DEFAULT 'UNKNOWN',
    CLIENT_IP      VARCHAR(200) NOT NULL DEFAULT '(none)',
    AUTH_FACTOR    VARCHAR(100) NOT NULL DEFAULT 'UNKNOWN',
    ERROR_CATEGORY VARCHAR(80) NOT NULL,
    LOGINS         NUMBER(14,0),
    SUCCESSES      NUMBER(14,0),
    FAILURES       NUMBER(14,0),
    FIRST_SEEN     TIMESTAMP_LTZ,
    LAST_SEEN      TIMESTAMP_LTZ,
    LOAD_TS        TIMESTAMP_NTZ NOT NULL DEFAULT CURRENT_TIMESTAMP()
);

CREATE TABLE IF NOT EXISTS DBA_MAINT_DB.OVERWATCH.FACT_SECURITY_CHANGE (
    QUERY_ID       VARCHAR(64) NOT NULL PRIMARY KEY,
    DAY            DATE NOT NULL,
    EVENT_TS       TIMESTAMP_LTZ NOT NULL,
    USER_NAME      VARCHAR(200),
    ROLE_NAME      VARCHAR(200),
    QUERY_TYPE     VARCHAR(80),
    DATABASE_NAME  VARCHAR(200),
    SCHEMA_NAME    VARCHAR(200),
    COMPANY        VARCHAR(40) NOT NULL DEFAULT 'UNKNOWN',
    CHANGE_KIND    VARCHAR(40),
    RISK_SCORE     NUMBER(5,0),
    RISK_LEVEL     VARCHAR(20),
    QUERY_PREVIEW  VARCHAR(200),
