        ('GOV_PTS_MFA_GAP',             '5'),
        ('GOV_PTS_EXPIRED_CRED',        '8'),
        ('GOV_PTS_EXPIRING_CRED',       '2'),
        ('GOV_PTS_BREAKGLASS_GRANT',    '6'),
